module DIV (
	aclr,
	clock,
	denom,
	numer,
	quotient,
	remain);

	input	  aclr;
	input	  clock;
	input	[3:0]  denom;
	input	[8:0]  numer;
	output	[8:0]  quotient;
	output	[3:0]  remain;

endmodule

